    "quote": "PCI is preferred if it can be delivered within 120 min of first medical contact (FMC). Thrombolysis is preferred if expected FMC-to-balloon time > 120 min. -For major PCI/urban centers, ideal FMC-to-balloon time is 90 minutes. -If thrombolysis is selected, door-to-needle time should be 30 minutes.",
    "statement": "The lecture favors thrombolysis when first-medical-contact-to-balloon time exceeds 120 minutes and gives a 30-minute door-to-needle target.",
