    "url": "https://drive.google.com/file/d/1Vl13g8KTcjkqeqSTegxBSqCyeAzRGuhI/view?usp=drivesdk",
    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "-Loud S1 Pliable MV when leaflets are still pliable, can be palpable (Tapping apex beat) -Loud P2 (due to pulmonary hypertension) which is followed by an opening snap -Opening snap Pliable MV of the mitral valve after a Normal S2: A high frequency, early in diastole, can mimic a split second heart sound. Caused by thickened valve leaflets as they open (Earlier OS indicates severe MS) Murmur: Low pitched mid-diastolic rumble at the apex with presystolic accentuation. The murmur is localised and does not radiate!",
    "statement": "The MS section describes loud S1, an opening snap and an apical mid-diastolic rumble.",
    "relation": "teaching",
    "sourceSha256": "e3f6819986a1a5818564cca8f399bc8afcb3ab32a5503c254ac59bb629296dd4",
