    "url": "https://drive.google.com/file/d/1PrgUki4ev_p-J7MjAjk1r0Bvl5ktaGm_/view?usp=drivesdk",
    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "They are not allergic to aspirin in the sense of anaphylaxis, but have an aberrant metabolism of arachidonic acid (oxygenase pathway).",
    "statement": "The AERD section describes abnormal arachidonic-acid metabolism. It does not explicitly state the cyclooxygenase-inhibition mechanism in this excerpt.",
    "relation": "background",
    "sourceSha256": "83b54ccedf790eec54f2dfdc6ea45f6ad17f6fc41fb9bee842a07d7641c8b3dd",
    "pageTextSha256": "5c9b54bce29a9b7c9a0e3486b7776e92f71a74e05b5b66b73c94ed6a920506a6",
    "note": "Background only: this passage does not establish the recorded answer."
