  "medicine-midterm-437-pulmonary-q015": {
    "title": "L1) Bronchial asthma",
    "pdfId": "1PrgUki4ev_p-J7MjAjk1r0Bvl5ktaGm_",
    "page": 14,
    "url": "https://drive.google.com/file/d/1PrgUki4ev_p-J7MjAjk1r0Bvl5ktaGm_/view?usp=drivesdk",
    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "Why not treat with SABA alone (Ventolin)? It treats the symptoms, not the disease. Up to 27% of asthma deaths are in patients with occasional symptoms. Exacerbation triggers are unpredictable. Overuse of SABA is associated with increased exacerbations and mortality. There is strong evidence for a more effective and Safer alternative (ICS-formeterol [Symbicort]) SYGMA 1 trial.",
    "statement": "The lecture rejects SABA-only treatment and describes ICS/formoterol as a safer alternative.",
    "relation": "teaching",
    "sourceSha256": "83b54ccedf790eec54f2dfdc6ea45f6ad17f6fc41fb9bee842a07d7641c8b3dd",
    "pageTextSha256": "a9b820a565a8f690e3731b9b475627888c4ef8952d6f4ba6ce6107a513a953e7",
    "note": "The clinical interpretation applies this teaching to the case; it is separate from the original lecture wording."
  },
