    "quote": "In severe hyperkalemia (K>6.5) with ECG changes or arrhythmia, we give IV calcium gluconate as a membrane stabilizer. It raises the resting membrane potential, making cardiac cells less excitable and reducing the risk of fatal arrhythmias. Important note: it does not lower potassium, it only stabilizes the myocardium.",
    "statement": "The lecture explicitly recommends IV calcium gluconate for severe hyperkalemia with ECG changes and notes that it stabilizes the heart without lowering potassium.",
    "relation": "teaching",
    "sourceSha256": "da623508bedfbe46d3170241775e3d3284b77e4fc1bdd367e5181a2461fa0505",
    "pageTextSha256": "d9dbff9781af23207a16a042815e3cd8faa32c141bb1ae20a23a83f803462f2d",
