    "quote": "Blood pressure control.[2] Glycemic control.[3] Renin angiotensin receptor inhibitors such as ACE inhibitors or ARB in patients who have proteinuric CKD.",
    "statement": "Blood-pressure control and RAAS inhibition in proteinuric CKD are listed under slowing progression.",
    "relation": "teaching",
    "sourceSha256": "32d20f6b4264ef5944c6ea03b83668a3db7b3e05b1534043eb6e1fc31d180df5",
    "pageTextSha256": "cc0a9c915c6183d17a0961d96f628712fb4a5d3bc730badec77f95f0753ee4a9",
