    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "Reduce phosphate intake to < 10 mg/kg/day (Diet control) Phosphate binders (Given with meals): 1. Calcium carbonate (439:Tackles hypocalcemia AND hyperphosphatemia, contraindicated with hypercalcaemia or. The problem is that people treat it as a supplement (don’t take it with meals) causes hypercalcemia and constipation.) 2. Sevelamer (Renagel) (Non-calcium phosphate binder, causes acidosis) 3. Lanthanum carbonate",
    "statement": "The lecture recommends phosphate restriction and binders, including calcium carbonate and sevelamer; binder selection depends on the calcium/phosphate context.",
    "relation": "teaching",
    "sourceSha256": "32d20f6b4264ef5944c6ea03b83668a3db7b3e05b1534043eb6e1fc31d180df5",
    "pageTextSha256": "1d6e16d43677baa0509ba67937edc059910d2dafdb3d57fd59c36f13e50b478f",
    "note": "The clinical interpretation applies this teaching to the case; it is separate from the original lecture wording."
