    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "We have to calculate the expected pCO2 then compare it with the pCO2 that was measured in the ABG If the measured pCO2 is more or less than the expected PCO2 that means there are no compensation So we have to check the appropriate response in the body, not the normal range (35-45)",
