    "url": "https://drive.google.com/file/d/1Qriuhbb34zoe496wiWlOMtZSxmVe-Tze/view?usp=drivesdk",
    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "PPIs can interfere with the diagnosis of H. pylori infection and peptic ulcer visibility during testing. If PUD is suspected, it’s recommended pausing the medication before testing for a more accurate diagnosis because it might cause a False negative result.)",
    "statement": "The lecture recommends withholding PPIs before H. pylori testing to reduce false negatives.",
    "relation": "teaching",
    "sourceSha256": "7b0a33852bb8c3de4fbf630c4e2ae9048e285fecff42081ce15ef07fbcc9e2ad",
    "pageTextSha256": "808d9f7b32b14333dc262fb2941727171e51030cee21389d5fa1530108fbc206",
