  "medicine-midterm-441-git-hepatobiliary-q058": {
    "title": "2) Abdominal Pain Including IBS.pdf",
    "pdfId": "1Qriuhbb34zoe496wiWlOMtZSxmVe-Tze",
    "page": 24,
    "url": "https://drive.google.com/file/d/1Qriuhbb34zoe496wiWlOMtZSxmVe-Tze/view?usp=drivesdk",
    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "Bismuth 525 mg, metronidazole 500 mg, tetracycline 500 mg all four times daily with PPI twice daily for 7-14 days. 1st line treatment in Saudi (7-14 days) but generally reserved for retreatment (14 days) Quadruple therapy can be used when there is resistance to clarithromycin in macrolide allergic patients PPI, amoxicillin 1 gm, metronidazole 500 mg all twice daily for 14 days Concomitant therapy Novel regimen which was proved successful in the presence of clarithromycin resistance. This is a 4-drug regimen containing a PPI ,clarithromycin (500 mg, b.i.d.), amoxicillin (1 g, b.i.d.) and metronidazole (500 mg, b.i.d.) which are all given for the entire duration of therapy. first line along with quadruple therapy in Saudi Arabia (if both are choices in the exam, choose quadruple)",
    "statement": "The lecture describes bismuth quadruple therapy and identifies it as first-line in Saudi Arabia.",
    "relation": "teaching",
    "sourceSha256": "7b0a33852bb8c3de4fbf630c4e2ae9048e285fecff42081ce15ef07fbcc9e2ad",
    "pageTextSha256": "4f1d8cf9443eb7a742dff24d93b00ae1a6a6fed34b852507ace25d456a3dd317",
    "note": "The clinical interpretation applies this teaching to the case; it is separate from the original lecture wording."
  },
  "medicine-midterm-439-nephrology-q052": {
    "title": "2) Abdominal Pain Including IBS.pdf",
    "pdfId": "1Qriuhbb34zoe496wiWlOMtZSxmVe-Tze",
    "page": 24,
    "url": "https://drive.google.com/file/d/1Qriuhbb34zoe496wiWlOMtZSxmVe-Tze/view?usp=drivesdk",
    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "Urea Breath Test (UBT): H. pylori urease converts radiolabeled urea (C14 or C13) to CO2 and ammonia; this test detects CO2 formed from urea metabolism. Has high sensitivity and specificity. PPIs may cause false results. 3) Stool antigen: Detects H. pylori antigens in stool. Cost-effective initial test for H.pylori. Patients should be off PPls for 2 weeks. 4) Both of UBT and stool antigen methods are good to measure the effect of treatment",
    "statement": "The lecture describes urea breath/stool antigen testing for treatment response and PPI-related false results.",
    "relation": "teaching",
    "sourceSha256": "7b0a33852bb8c3de4fbf630c4e2ae9048e285fecff42081ce15ef07fbcc9e2ad",
    "pageTextSha256": "4f1d8cf9443eb7a742dff24d93b00ae1a6a6fed34b852507ace25d456a3dd317",
    "note": "The clinical interpretation applies this teaching to the case; it is separate from the original lecture wording."
  },
