    "extraction": "pdfplumber-text-flow-whitespace-only",
    "verified": true,
    "quote": "Example of Intermediate likelihood: If a patient presents with mildly elevated liver enzymes and bilirubin, the mild elevation is usually attributable to stones. Therefore, you don’t do ERCP right away because the stone may have already passed or may be only partially obstructing. In this case, you should do MRCP or EUS first.",
